SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY 1,2;

SELECT table_schema, table_name, column_name FROM information_schema.columns
WHERE table_schema IN ('store','warehouse','payments') AND column_name ~* 'price|amount|revenue|cost|value'
ORDER BY 1,2,3;

SELECT count(DISTINCT bill_id) AS bills, count(DISTINCT split_part(bill_id,'-',1)) AS prefixes,
       min(length(bill_id)) AS minlen, max(length(bill_id)) AS maxlen
FROM store.pos_lines;

SELECT sku_scanned, unit_price, count(*) n, min(bill_ts) mn, max(bill_ts) mx
FROM store.pos_lines
GROUP BY 1,2 ORDER BY 1,2;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;

SELECT table_schema, table_name, table_type FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;
